css:
.switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20vmin;
  height: 10vmin;
  background: #141414;
  border-radius: 5vmin;
  overflow: hidden;
  box-shadow:
    0 0 0.1vmin 0.1vmin #000000,
    0 0 0.5vmin 0.1vmin #0b0b10 inset;
  cursor: pointer;
}

.switch input {
  display: none;
}

.thumb {
  position: absolute;
  width: 8.75vmin;
  height: 8.75vmin;
  top: 0.6vmin;
  left: calc(100% - 9.333vmin);
  border-radius: 5vmin;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  animation: move-skull-left 0.5s ease-in-out 0.5s forwards;
}

.switch input:checked ~ .thumb {
  left: 0.6vmin;
  animation: move-skull-right 0.5s ease-in-out 0.5s forwards;
}

@keyframes move-skull-right {
  0% {
    left: 0.6vmin;
  }
  100% {
    left: calc(100% - 9.333vmin);
  }
}

@keyframes move-skull-left {
  0% {
    left: calc(100% - 9.333vmin);
  }
  100% {
    left: 0.6vmin;
  }
}

/*** Skull ***/

.thumb > * {
  position: absolute;
  filter: drop-shadow(0px 1px 1px #000);
  animation: unselected 1.5s ease-in-out 0s reverse forwards;
}

.switch input:checked ~ .thumb * {
  animation: selected 1.5s ease-in-out 0s forwards;
}

@keyframes selected {
  0%,
  50% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1);
  }
  50.01%,
  100% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1.875);
  }
}

@keyframes unselected {
  0%,
  50% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1);
  }
  50.01%,
  100% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1.875);
  }
}

.cranium {
  background: linear-gradient(180deg, #888 0 54%, #fff0 0 94%, #888 0 100%),
    radial-gradient(
      circle at 75% 69%,
      #fff0 0 0.875vmin,
      #888 calc(0.875vmin + 1px) 2.425vmin,
      #fff0 calc(2.425vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 25% 69%,
      #fff0 0 0.875vmin,
      #888 calc(0.875vmin + 1px) 2.425vmin,
      #fff0 calc(2.425vmin + 1px) 100%
    );
  width: 100%;
  height: 7vmin;
  left: 0;
  top: 0;
  border-radius: 5vmin 5vmin 2.75vmin 2.75vmin;
}

.cranium:before {
  content: "";
  position: absolute;
  width: 0.625vmin;
  height: 0.625vmin;
  bottom: -0.375vmin;
  left: 3.75vmin;
  background: #888;
  border-radius: 100%;
  box-shadow: 0.625vmin 0 0 0 #888;
}

.cranium:after {
  content: "";
  position: absolute;
  width: 2.625vmin;
  height: 0.75vmin;
  bottom: -0.475vmin;
  left: 3vmin;
  background: radial-gradient(
      circle at 90% 10%,
      #888 0 0.5vmin,
      #fff0 calc(0.5vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 10% 10%,
      #888 0 0.5vmin,
      #fff0 calc(0.5vmin + 1px) 100%
    );
  border-radius: 0.5vmin;
}

.mouth {
  border: 0.425vmin solid #fff0;
  border-bottom-color: #888;
  width: 5.875vmin;
  left: 1.425vmin;
  height: 3vmin;
  top: 5.625vmin;
  background: radial-gradient(
      circle at 35% 98%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 45% 100%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 55% 100%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 65% 98%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    );
  background-repeat: no-repeat;
  border-radius: 100%;
}

.mouth:before,
.mouth:after {
  content: "";
  position: absolute;
  border-radius: 100%;
  background: #888;
  width: 0.35vmin;
  height: 0.35vmin;
  left: 0.2vmin;
  bottom: 0.125vmin;
}

.mouth:after {
  left: 4.525vmin;
}

/*** Arm ***/

@keyframes check-on {
  0% {
    right: -65%;
  }
  25%,
  33% {
    right: 0%;
  }
  66%,
  80% {
    right: -50%;
  }
  100% {
    right: -65%;
  }
}

@keyframes check-off {
  0% {
    right: -65%;
  }
  25%,
  33% {
    right: 0%;
  }
  66%,
  80% {
    right: -50%;
  }
  100% {
    right: -65%;
  }
}

.arm-wrapper {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 5vmin;
  overflow: hidden;
  right: -65%;
  animation: check-off 1.5s ease-in-out 0s reverse forwards;
}

.switch input:checked ~ .arm-wrapper {
  animation: check-on 1.5s ease-in-out 0s forwards;
}

.arm {
  position: absolute;
  width: 8vmin;
  height: 2.5vmin;
  right: 2%;
  top: calc(50% - 1.25vmin);
  border-radius: 0.125vmin;
}

.bone {
  background: #fff;
  width: 4vmin;
  height: 1vmin;
  position: absolute;
  transform: rotate(0deg);
  top: 0.75vmin;
  right: -2vmin;
}

.bone:before,
.bone:after,
.big:before,
.big:after {
  content: "";
  background: #fff;
  width: 0.75vmin;
  height: 0.75vmin;
  position: absolute;
  left: -0.25vmin;
  top: -0.25vmin;
  border-radius: 100%;
  box-shadow: 4vmin 0 0 0 #fff;
}

.bone:after {
  top: calc(100% - 0.5vmin);
}

.arm > .bone + .bone {
  top: 0.75vmin;
  left: 0.25vmin;
  height: 0.425vmin;
  width: 5.25vmin;
  box-shadow: 0 0.575vmin 0 0 #fff;
}
.arm > .bone + .bone:before,
.arm > .bone + .bone:after {
  box-shadow: 5.075vmin 0 0 0 #fff;
}

.arm > .bone + .bone:after {
  top: 100%;
}

/*** Hand ***/

.hand {
  position: absolute;
  background: radial-gradient(
      circle at 91% 29%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 92% 49%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 91% 69%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 76% 21%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 78% 39%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 79% 58%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 78% 78%,
      #fff 0.25vmin,
      #fff0 calc(0.25vmin + 1px) 100%
    );
  width: 3.5vmin;
  height: 2.5vmin;
  left: -3.5vmin;
  z-index: 0;
}

.hand .bone,
.big {
  width: 1.5vmin;
  left: 0.675vmin;
  height: 0.375vmin;
  border-radius: 0.25vmin 0 0 0.25vmin;
}

.hand .bone:before,
.hand .bone:after,
.big:before,
.big:after {
  width: 0.4vmin;
  height: 0.4vmin;
  top: -0.125vmin;
  left: 1.125vmin;
  box-shadow: none;
}
.hand .bone:after,
.big:after {
  top: 0.0625vmin;
}

.hand .bone:nth-child(1) {
  transform: rotate(5deg) translateY(-0.5vmin) translateX(0.075vmin);
  filter: drop-shadow(-1.5vmin 0vmin 0px #fff);
}

.hand .bone:nth-child(2) {
  transform: rotate(0deg) translateX(0.25vmin);
  filter: drop-shadow(-1.5vmin 0vmin 0px #fff);
}

.hand .bone:nth-child(3) {
  transform: rotate(-2deg) translateY(0.575vmin) translateX(0.25vmin);
  filter: drop-shadow(-1.5vmin 0vmin 0px #fff);
}

.hand .bone:nth-child(4) {
  transform: rotate(-5deg) translateY(1.15vmin) translateX(0.25vmin);
  filter: drop-shadow(-1.5vmin 0vmin 0px #fff);
}

.big {
  background: #fff;
  height: 0.5vmin !important;
  position: absolute;
  left: -2.125vmin !important;
  top: 0.575vmin;
  z-index: 1;
  filter: drop-shadow(-1.25vmin 0vmin 0px #fff) drop-shadow(0 0 1px #000);
}
